#!/bin/sh
set -eu

until wp db check --allow-root >/dev/null 2>&1; do sleep 2; done
site_url="${KILN_CLEANUP_SITE_URL:-http://localhost:8080}"
wp core is-installed --allow-root >/dev/null 2>&1 || wp core install --url="$site_url" --title='Kiln Cleanup Smoke' --admin_user=admin --admin_password=not-a-real-secret --admin_email=admin@example.test --skip-email --allow-root
wp option update home "$site_url" --allow-root
wp option update siteurl "$site_url" --allow-root
rm -rf wp-content/plugins/kiln-cleanup
cp -R /workspace/kiln-cleanup wp-content/plugins/kiln-cleanup
mkdir -p wp-content/plugins/kiln-cleanup/vendor
cat > wp-content/plugins/kiln-cleanup/vendor/autoload.php <<'PHP'
<?php
spl_autoload_register(static function (string $class): void {
    if (str_starts_with($class, 'KilnCleanup\\')) {
        require __DIR__ . '/../src/' . str_replace('\\', '/', substr($class, 12)) . '.php';
    }
});
PHP
wp plugin activate kiln-cleanup --allow-root
wp eval 'global $wpdb; foreach (["kiln_cleanup_jobs","kiln_cleanup_candidates","kiln_cleanup_audit_events","kiln_cleanup_quarantines"] as $table) { if ($wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $wpdb->prefix . $table)) !== $wpdb->prefix . $table) { throw new RuntimeException("Missing table: " . $table); }}' --allow-root
wp eval 'global $wpdb; foreach (["band","policy_version"] as $column) { if ($wpdb->get_var("SHOW COLUMNS FROM {$wpdb->prefix}kiln_cleanup_candidates LIKE \"{$column}\"") !== $column) { throw new RuntimeException("Missing candidate column: " . $column); }} $bandColumn = $wpdb->get_row("SHOW COLUMNS FROM {$wpdb->prefix}kiln_cleanup_candidates LIKE \"band\"", ARRAY_A); if (($bandColumn["Type"] ?? "") !== "varchar(32)") { throw new RuntimeException("Candidate band column is too narrow"); } $codec = new \KilnCleanup\Application\ReviewJobSnapshotCodec(); $job = (new \KilnCleanup\Infrastructure\WpdbReviewJobRepository())->create($codec->policySnapshot(new \KilnCleanup\Detection\DetectionPolicy("smoke-v1")), $codec->filterSnapshot(new \KilnCleanup\Domain\InventoryFilter()), 1); if ($job->state->value !== "draft") { throw new RuntimeException("Unexpected new job state"); }' --allow-root
wp eval 'global $wpdb; $userId = wp_create_user("quarantine-smoke", "not-a-real-secret", "quarantine-smoke@example.test"); (new WP_User($userId))->set_role("subscriber"); $codec = new \KilnCleanup\Application\ReviewJobSnapshotCodec(); $jobs = new \KilnCleanup\Infrastructure\WpdbReviewJobRepository(); $job = $jobs->create($codec->policySnapshot(new \KilnCleanup\Detection\DetectionPolicy("quarantine-smoke-v1")), $codec->filterSnapshot(new \KilnCleanup\Domain\InventoryFilter()), 1); $wpdb->update($wpdb->prefix . "kiln_cleanup_jobs", ["state" => "completed"], ["id" => $job->id]); (new \KilnCleanup\Infrastructure\WpdbCandidateSnapshotRepository())->insert(new \KilnCleanup\Domain\CandidateSnapshot($job->id, $userId, 75, "eligible_for_quarantine", "quarantine-smoke-v1", ["blocked_email_domain"])); $service = new \KilnCleanup\Application\QuarantineService(new \KilnCleanup\Infrastructure\WpdbQuarantineCandidateRepository(), new \KilnCleanup\Infrastructure\WpdbQuarantineRepository(), new \KilnCleanup\Infrastructure\WordPressUserAccountGateway(), new \KilnCleanup\Infrastructure\QuarantineAuditRecorder()); $service->quarantine($job->id, $userId, new \KilnCleanup\Detection\DetectionPolicy("quarantine-smoke-v1"), 1); if (get_user_meta($userId, "_kiln_cleanup_quarantined", true) !== "1") { throw new RuntimeException("Quarantine marker missing"); } if ((new WP_User($userId))->has_cap("read")) { throw new RuntimeException("Quarantine retained account access"); } $service->restore($userId, 1); if (get_user_meta($userId, "_kiln_cleanup_quarantined", true) !== "") { throw new RuntimeException("Quarantine marker remained after restore"); } if (! (new WP_User($userId))->has_cap("read")) { throw new RuntimeException("Restore did not return subscriber capabilities"); } $events = $wpdb->get_col($wpdb->prepare("SELECT event_type FROM {$wpdb->prefix}kiln_cleanup_audit_events WHERE target_user_id = %d", $userId)); if (! in_array("account_quarantined", $events, true) || ! in_array("account_restored", $events, true)) { throw new RuntimeException("Quarantine audit receipts missing"); }' --allow-root
wp eval 'global $wpdb; $candidate = $wpdb->get_row("SELECT job_id, user_id FROM {$wpdb->prefix}kiln_cleanup_candidates ORDER BY id DESC LIMIT 1", ARRAY_A); $service = new \KilnCleanup\Application\QuarantineService(new \KilnCleanup\Infrastructure\WpdbQuarantineCandidateRepository(), new \KilnCleanup\Infrastructure\WpdbQuarantineRepository(), new \KilnCleanup\Infrastructure\WordPressUserAccountGateway(), new \KilnCleanup\Infrastructure\QuarantineAuditRecorder()); $service->quarantine((int) $candidate["job_id"], (int) $candidate["user_id"], new \KilnCleanup\Detection\DetectionPolicy("quarantine-smoke-v1"), 1); $service->restore((int) $candidate["user_id"], 1); if ((int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}kiln_cleanup_quarantines WHERE user_id = %d", (int) $candidate["user_id"])) !== 2) { throw new RuntimeException("Repeated quarantine did not retain separate history"); }' --allow-root
wp eval 'global $wpdb; foreach (["claim_token", "claim_expires_at", "last_error"] as $column) { if ($wpdb->get_var("SHOW COLUMNS FROM {$wpdb->prefix}kiln_cleanup_jobs LIKE \"{$column}\"") !== $column) { throw new RuntimeException("Missing M7 job column: " . $column); }} if (! wp_next_scheduled("kiln_cleanup_run_review_jobs")) { throw new RuntimeException("M7 review worker cron event is not scheduled"); }' --allow-root
wp kiln-cleanup review-jobs run --batches=1 --batch-size=25 --allow-root
wp eval 'do_action("admin_menu");' --allow-root
wp plugin is-active kiln-cleanup --allow-root
echo "Container smoke checks passed."
